ce_require_admin(); ce_install($conn);
function ce_ids(string $field): array { $v=$_POST[$field]??[];if(!is_array($v))$v=[];return array_values(array_unique(array_filter(array_map('intval',$v),fn($x)=>$x>0))); }
function ce_save_map(mysqli $conn,string $table,string $fk,int $id,array $ids): void { $s=$conn->prepare("DELETE FROM `$table` WHERE `$fk`=?");$s->bind_param('i',$id);$s->execute();$s->close();if(!$ids)return;$s=$conn->prepare("INSERT INTO `$table`(`$fk`,department_id) VALUES(?,?)");foreach($ids as $did){$s->bind_param('ii',$id,$did);$s->execute();}$s->close(); }
try{
ce_verify_csrf();$action=(string)($_POST['action']??'');
if($action==='save_theme'){
$id=(int)($_POST['id']??0);$year=(int)($_POST['theme_year']??date('Y'));$en=trim((string)($_POST['english_theme']??''));$lname=trim((string)($_POST['local_language_name']??'Local Language'));$local=trim((string)($_POST['local_theme']??''));$scripture=trim((string)($_POST['scripture_reference']??''));$ex=trim((string)($_POST['explanation']??''));$active=isset($_POST['is_active'])?1:0;$aud=(string)($_POST['audience']??'All Members');$aud=$aud==='Selected Departments'?'Selected Departments':'All Members';$deps=$aud==='Selected Departments'?ce_ids('department_ids'):[];if($en===''||$local==='')throw new RuntimeException('English and local-language themes are required.');if($year<2000||$year>2100)throw new RuntimeException('Enter a valid theme year.');if($aud==='Selected Departments'&&!$deps)throw new RuntimeException('Select at least one department.');
if($id>0){$s=$conn->prepare('UPDATE church_annual_themes SET theme_year=?,english_theme=?,local_language_name=?,local_theme=?,scripture_reference=?,explanation=?,audience=?,is_active=? WHERE id=?');$s->bind_param('issssssii',$year,$en,$lname,$local,$scripture,$ex,$aud,$active,$id);}else{$uid=ce_user_id();$s=$conn->prepare('INSERT INTO church_annual_themes(theme_year,english_theme,local_language_name,local_theme,scripture_reference,explanation,audience,is_active,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('issssssii',$year,$en,$lname,$local,$scripture,$ex,$aud,$active,$uid);}if(!$s->execute())throw new RuntimeException($s->error);if($id===0)$id=$s->insert_id;$s->close();ce_save_map($conn,'church_theme_departments','theme_id',$id,$deps);ce_flash('success','Annual theme saved successfully.');
}elseif($action==='delete_theme'){$id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Invalid theme.');ce_save_map($conn,'church_theme_departments','theme_id',$id,[]);$s=$conn->prepare('DELETE FROM church_annual_themes WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();ce_flash('success','Annual theme deleted.');
}elseif($action==='save_harvest'){
$id=(int)($_POST['id']??0);$year=(int)($_POST['harvest_year']??date('Y'));$name=trim((string)($_POST['harvest_name']??''));$category=(string)($_POST['harvest_category']??'General');if(!in_array($category,['Zone','Sunday School','General'],true))$category='General';$zoneId=(int)($_POST['zone_id']??0);$zone='';if($category!=='Zone')$zoneId=0;$target=max(0,(float)($_POST['target_amount']??0));$collected=max(0,(float)($_POST['amount_collected']??0));$date=trim((string)($_POST['harvest_date']??''));$notes=trim((string)($_POST['notes']??''));$status=(string)($_POST['status']??'Open');if(!in_array($status,['Planning','Open','Completed','Cancelled'],true))$status='Open';$aud=(string)($_POST['audience']??'All Members');$aud=$aud==='Selected Departments'?'Selected Departments':'All Members';$deps=$aud==='Selected Departments'?ce_ids('department_ids'):[];if($name==='')throw new RuntimeException('Harvest name is required.');if($year<2000||$year>2100)throw new RuntimeException('Enter a valid harvest year.');if($category==='Zone'){
    if($zoneId<1)throw new RuntimeException('Select a church zone for a Zone harvest.');
    $zs=$conn->prepare('SELECT zone_name FROM church_zones WHERE id=? LIMIT 1');
    if(!$zs)throw new RuntimeException('Unable to validate the selected church zone.');
    $zs->bind_param('i',$zoneId);$zs->execute();$zr=$zs->get_result()->fetch_assoc();$zs->close();
    if(!$zr)throw new RuntimeException('The selected church zone is invalid.');
    $zone=trim((string)$zr['zone_name']);
}if($aud==='Selected Departments'&&!$deps)throw new RuntimeException('Select at least one department.');
if($id>0){$s=$conn->prepare("UPDATE church_harvests SET harvest_year=?,harvest_name=?,harvest_category=?,zone_id=NULLIF(?,0),zone_name=NULLIF(?,''),target_amount=?,amount_collected=?,harvest_date=NULLIF(?,''),notes=?,audience=?,status=? WHERE id=?");$s->bind_param('issisddssssi',$year,$name,$category,$zoneId,$zone,$target,$collected,$date,$notes,$aud,$status,$id);}else{$uid=ce_user_id();$s=$conn->prepare("INSERT INTO church_harvests(harvest_year,harvest_name,harvest_category,zone_id,zone_name,target_amount,amount_collected,harvest_date,notes,audience,status,created_by) VALUES(?,?,?,NULLIF(?,0),NULLIF(?,''),?,?,NULLIF(?,''),?,?,?,?)");$s->bind_param('issisddssssi',$year,$name,$category,$zoneId,$zone,$target,$collected,$date,$notes,$aud,$status,$uid);}if(!$s->execute())throw new RuntimeException($s->error);if($id===0)$id=$s->insert_id;$s->close();ce_save_map($conn,'church_harvest_departments','harvest_id',$id,$deps);ce_flash('success','Harvest saved successfully.');
}elseif($action==='delete_harvest'){$id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Invalid harvest.');ce_save_map($conn,'church_harvest_departments','harvest_id',$id,[]);$s=$conn->prepare('DELETE FROM church_harvests WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();ce_flash('success','Harvest deleted.');
}else throw new RuntimeException('Invalid action.');
}catch(Throwable $e){ce_flash('danger',$e->getMessage());}
ce_redirect((string)($_POST['return_to']??'../harvests/'));
